const body = $input.first().json.body || $input.first().json;
const event = body.event || '';
const payment = body.payment || body;

const eventosValidos = ['PAYMENT_CONFIRMED', 'PAYMENT_RECEIVED'];
if (!eventosValidos.includes(event)) {
  return [{ json: { ignorar: true, motivo: 'Evento ignorado: ' + event } }];
}

let metadata = {};
try {
  metadata = payment.externalReference
    ? JSON.parse(payment.externalReference)
    : {};
} catch(e) { metadata = {}; }

return [{
  json: {
    ignorar: false,
    asaas_customer_id: payment.customer || '',
    asaas_payment_id:  payment.id || '',
    valor_pago:        payment.value || 0,
    email:             metadata.email || payment.customerEmail || '',
    nome_negocio:      metadata.nome_negocio || '',
    tenant_id:         metadata.tenant_id || '',
    metadata:          metadata
  }
}];

